mapper.select:
SELECT * FROM course

    AND (course_name LIKE CONCAT('%',#{keyword},'%') OR course_code LIKE CONCAT('%',#{keyword},'%'))
    AND teacher_id = #{teacherId}
    AND class_name LIKE CONCAT('%',#{className},'%')

ORDER BY create_time DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE course
course_name = #{courseName}, classroom = #{classroom}, week_day = #{weekDay}, start_time = #{startTime}, end_time = #{endTime}, week_start = #{weekStart}, week_end = #{weekEnd}, status = #{status},
WHERE id = #{id}
